select t1.* from ( SELECT bpmol.occur_log_id occurLogId, DATE_FORMAT(bpmol.occur_date, '%Y-%m-%d') occurDate, bpt.patient_id patientId, bpt.NAME, bpt.mobile, bpm.card_number cardNumber, IFNULL(bpmol.principal_amount,0) principalAmount, IFNULL(bpmol.bonus_amount,0) bonusAmount, IFNULL( bpmol.current_recharge_principal + bpmol.current_recharge_bonus ,0) currentRechargePrincipal, IFNULL( bpm.principal_amount + bpm.bonus_amount ,0) currentAmount, bpmol.payment_id paymentId, CASE WHEN bpmol.recharge_method = '0' THEN'手动充值' ELSE '充值卡充值' END AS 'rechargeMethod', bpmol.payment_manner paymentManner, bpmol.recharge_card_number rechargeCardNumber, bpmol.operator_user_id, ( SELECT be.employee_name FROM base_employee be WHERE be.user_id = bpmol.operator_user_id ) operatorUserName, bpmol.remarks FROM base_patient_member_occur_log bpmol JOIN base_patient bpt ON bpmol.patient_id = bpt.patient_Id JOIN base_patient_member bpm ON bpm.card_id = bpmol.card_id
bpmol.type = 1 AND bpmol.occur_type = 1
AND bpmol.org_id = #{form.orgId}
AND bpm.card_number = #{form.cardNumber}
and DATE_FORMAT(bpmol.occur_date, '%Y-%m-%d') >= DATE_FORMAT(#{form.startDate}, '%Y-%m-%d') and DATE_FORMAT(bpmol.occur_date, '%Y-%m-%d') < DATE_FORMAT(#{form.endDate}, '%Y-%m-%d')
AND bpmol.recharge_method in
#{rechargeMethod}
group by bpmol.occur_date desc ) t1
AND t1.patientId in
#{ids}

