select t1.* from ( SELECT bpmol.occur_log_id occurLogId, DATE_FORMAT(bpmol.occur_date, '%Y-%m-%d') occurDate, bpt.patient_id patientId, bpt.NAME, bpt.mobile, bpm.card_number cardNumber, IFNULL(bpmol.principal_amount,0) principalAmount, IFNULL(bpmol.bonus_amount,0) bonusAmount, IFNULL( bpmol.current_recharge_principal + bpmol.current_recharge_bonus ,0) currentReturnPrincipal, IFNULL( bpm.principal_amount + bpm.bonus_amount ,0) currentAmount, bpmol.payment_id paymentId, bpmol.payment_manner paymentManner, bpmol.operator_user_id, (select be.employee_name from base_employee be where be.user_id = bpmol.operator_user_id) operatorUserName, bpmol.remarks FROM base_patient_member_occur_log bpmol JOIN base_patient bpt ON bpmol.patient_id = bpt.patient_Id JOIN base_patient_member bpm ON bpm.patient_id = bpt.patient_Id
bpmol.type = 1 and bpmol.occur_type = 3
and bpmol.org_id = #{form.orgId}
and bpm.card_number = #{form.cardNumber}
and DATE_FORMAT(bpmol.occur_date, '%Y-%m-%d') >= DATE_FORMAT(#{form.startDate}, '%Y-%m-%d') and DATE_FORMAT(bpmol.occur_date, '%Y-%m-%d') < DATE_FORMAT(#{form.endDate}, '%Y-%m-%d')
group by bpmol.occur_date desc) t1
