SELECT bpmor.rechargeRecordId, bpmor.rechargeDate, bpmor.patientId, bpmor.patientName, bpmor.patientMobile, bpmor.patientCardId, bpmor.patientCardNumber, bpmor.cardTypeName, bpmor.rechargePrincipleAmount, bpmor.rechargeBonusAmount, IFNULL( bpmor.totalAmount, 0 ) AS restTotalAmount, bpmor.rechargeOperatorId, bpmor.rechargeOperatorName FROM ( SELECT bpmor.occur_log_id AS rechargeRecordId, DATE_FORMAT( bpmor.occur_date, '%Y-%m-%d' ) rechargeDate, bpmor.patient_id AS patientId, bp.`name` AS patientName, bp.mobile AS patientMobile, bp.pinyin_name AS pinyinName, bpmor.card_id AS patientCardId, bpm.card_number AS patientCardNumber, IFNULL(bpm.member_level_name, '预付款') AS cardTypeName, IFNULL(bpmor.principal_amount, 0) AS rechargePrincipleAmount, IFNULL(bpmor.bonus_amount, 0) AS rechargeBonusAmount, ( bpm.bonus_amount + bpm.principal_amount ) AS totalAmount, bpmor.operator_user_id AS rechargeOperatorId, be.employee_name AS rechargeOperatorName FROM base_patient_member_occur_log bpmor LEFT JOIN base_patient bp ON bpmor.patient_id = bp.patient_id LEFT JOIN base_patient_member bpm ON bpmor.card_id = bpm.card_id AND bpmor.type = bpm.type LEFT JOIN base_employee be ON bpmor.operator_user_id = be.user_id
AND bpmor.occur_type = 1 -- 表示充值
AND bpmor.org_id = #{query.orgId}
-- 0:会员卡；1：预付款卡 AND bpmor.type = #{query.cardType}
AND DATE_FORMAT(bpmor.occur_date, '%Y-%m-%d') >= #{query.startDate}
AND DATE_FORMAT(bpmor.occur_date, '%Y-%m-%d') <= #{query.endDate}
AND DATE_FORMAT(bpmor.occur_date, '%Y-%m') >= #{query.startDate}
AND DATE_FORMAT(bpmor.occur_date, '%Y-%m') <= #{query.endDate}
AND DATE_FORMAT(bpmor.occur_date, '%Y') >= #{query.startDate}
AND DATE_FORMAT(bpmor.occur_date, '%Y') <= #{query.endDate}
ORDER BY bpmor.occur_date DESC ) bpmor
AND concat(IFNULL(bpmor.patientName, ''), IFNULL(bpmor.pinyinName, ''), IFNULL(bpmor.patientMobile, '')) like concat('%', #{query.patientKeyword}, '%')
AND bpmor.patientCardNumber like concat('%', #{query.cardNum}, '%')
AND bpmor.rechargeDate >= #{query.rechargeStartDate}
AND bpmor.rechargeDate <= #{query.rechargeEndDate}

SELECT bpmor.refundRecordId, bpmor.refundDate, bpmor.patientId, bpmor.patientName, bpmor.patientMobile, bpmor.patientCardId, bpmor.patientCardNumber, bpmor.cardTypeName, bpmor.refundPrincipleAmount, bpmor.refundBonusAmount, IFNULL( bpmor.totalAmount, 0 ) AS restTotalAmount, bpmor.refundOperatorId, bpmor.refundOperatorName FROM ( SELECT bpmor.occur_log_id AS refundRecordId, DATE_FORMAT( bpmor.occur_date, '%Y-%m-%d' ) refundDate, bpmor.patient_id AS patientId, bp.`name` AS patientName, bp.mobile AS patientMobile, bp.pinyin_name AS pinyinName, bpmor.card_id AS patientCardId, bpm.card_number AS patientCardNumber, IFNULL(bpm.member_level_name, '预付款') AS cardTypeName, IFNULL(bpmor.principal_amount, 0) AS refundPrincipleAmount, IFNULL(bpmor.bonus_amount, 0) AS refundBonusAmount, ( bpm.bonus_amount + bpm.principal_amount ) AS totalAmount, bpmor.operator_user_id AS refundOperatorId, be.employee_name AS refundOperatorName FROM base_patient_member_occur_log bpmor LEFT JOIN base_patient bp ON bpmor.patient_id = bp.patient_id LEFT JOIN base_patient_member bpm ON bpmor.card_id = bpm.card_id AND bpmor.type = bpm.type LEFT JOIN base_employee be ON bpmor.operator_user_id = be.user_id
AND bpmor.occur_type = 3 -- 表示退费
AND bpmor.org_id = #{query.orgId}
-- 0:会员卡；1：预付款卡 AND bpmor.type = #{query.cardType}
AND DATE_FORMAT(bpmor.occur_date, '%Y-%m-%d') >= #{query.startDate}
AND DATE_FORMAT(bpmor.occur_date, '%Y-%m-%d') <= #{query.endDate}
AND DATE_FORMAT(bpmor.occur_date, '%Y-%m') >= #{query.startDate}
AND DATE_FORMAT(bpmor.occur_date, '%Y-%m') <= #{query.endDate}
AND DATE_FORMAT(bpmor.occur_date, '%Y') >= #{query.startDate}
AND DATE_FORMAT(bpmor.occur_date, '%Y') <= #{query.endDate}
ORDER BY bpmor.occur_date DESC ) bpmor
AND concat(IFNULL(bpmor.patientName, ''), IFNULL(bpmor.pinyinName, ''), IFNULL(bpmor.patientMobile, '')) like concat('%', #{query.patientKeyword}, '%')
AND bpmor.patientCardNumber like concat('%', #{query.cardNum}, '%')
AND bpmor.refundDate >= #{query.refundStartDate}
AND bpmor.refundDate <= #{query.refundEndDate}
